using namespace std;

class Solution {
    vector<int> tree;
    int n;

    void build(const vector<int>& baskets, int node, int start, int end) {
        if (start == end) {
            tree[node] = baskets[start];
            return;
        }
        int mid = (start + end) / 2;
        build(baskets, 2 * node + 1, start, mid);
        build(baskets, 2 * node + 2, mid + 1, end);
        tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
    }

    int queryAndUpdate(int node, int start, int end, int target) {
        if (tree[node] < target) return -1;
        if (start == end) {
            tree[node] = -1;
            return start;
        }
        int mid = (start + end) / 2;
        int res = -1;
        if (tree[2 * node + 1] >= target) {
            res = queryAndUpdate(2 * node + 1, start, mid, target);
        } else {
            res = queryAndUpdate(2 * node + 2, mid + 1, end, target);
        }
        tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
        return res;
    }

public:
    int numOfUnplacedFruits(vector<int>& fruits, vector<int>& baskets) {
        n = baskets.size();
        tree.assign(4 * n, 0);
        build(baskets, 0, 0, n - 1);

        int unplaced = 0;
        for (int fruit : fruits) {
            int idx = queryAndUpdate(0, 0, n - 1, fruit);
            if (idx == -1) unplaced++;
        }
        return unplaced;
    }
};

class Solution {
    private int[] tree;

    private void build(int[] baskets, int node, int start, int end) {
        if (start == end) {
            tree[node] = baskets[start];
            return;
        }
        int mid = (start + end) / 2;
        build(baskets, 2 * node + 1, start, mid);
        build(baskets, 2 * node + 2, mid + 1, end);
        tree[node] = Math.max(tree[2 * node + 1], tree[2 * node + 2]);
    }

    private int queryAndUpdate(int node, int start, int end, int target) {
        if (tree[node] < target) return -1;
        if (start == end) {
            tree[node] = -1;
            return start;
        }
        int mid = (start + end) / 2;
        int res;
        if (tree[2 * node + 1] >= target) {
            res = queryAndUpdate(2 * node + 1, start, mid, target);
        } else {
            res = queryAndUpdate(2 * node + 2, mid + 1, end, target);
        }
        tree[node] = Math.max(tree[2 * node + 1], tree[2 * node + 2]);
        return res;
    }

    public int numOfUnplacedFruits(int[] fruits, int[] baskets) {
        int n = baskets.length;
        tree = new int[4 * n];
        build(baskets, 0, 0, n - 1);

        int unplaced = 0;
        for (int fruit : fruits) {
            int idx = queryAndUpdate(0, 0, n - 1, fruit);
            if (idx == -1) unplaced++;
        }
        return unplaced;
    }
}

