var numOfUnplacedFruits = function(fruits, baskets) {
    const n = baskets.length;
    const tree = new Array(4 * n).fill(0);

    function build(node, start, end) {
        if (start === end) {
            tree[node] = baskets[start];
            return;
        }
        const mid = (start + end) >> 1;
        build(2 * node + 1, start, mid);
        build(2 * node + 2, mid + 1, end);
        tree[node] = Math.max(tree[2 * node + 1], tree[2 * node + 2]);
    }

    function queryAndUpdate(node, start, end, target) {
        if (tree[node] < target) return -1;
        if (start === end) {
            tree[node] = -1;
            return start;
        }
        const mid = (start + end) >> 1;
        let res;
        if (tree[2 * node + 1] >= target) {
            res = queryAndUpdate(2 * node + 1, start, mid, target);
        } else {
            res = queryAndUpdate(2 * node + 2, mid + 1, end, target);
        }
        tree[node] = Math.max(tree[2 * node + 1], tree[2 * node + 2]);
        return res;
    }

    build(0, 0, n - 1);
    let unplaced = 0;
    for (const fruit of fruits) {
        const idx = queryAndUpdate(0, 0, n - 1, fruit);
        if (idx === -1) unplaced++;
    }
    return unplaced;
};
